        "dusk" -> d.copy(background = Color(0xFF122319), surface = Color(0xFF122319), surfaceDim = Color(0xFF122319), surfaceBright = Color(0xFF3E4F44), surfaceContainerLowest = Color(0xFF0A1B12), surfaceContainerLow = Color(0xFF19291F),
            surfaceContainer = Color(0xFF1F3025), surfaceContainerHigh = Color(0xFF28392E), surfaceContainerHighest = Color(0xFF304236), surfaceVariant = Color(0xFF304236), onSurfaceVariant = Color(0xFFA7C2AF), outlineVariant = Color(0xFF3D5546))
        "oled" -> d.copy(background = Color.Black, surface = Color.Black, surfaceDim = Color.Black, surfaceContainerLowest = Color.Black, surfaceContainerLow = Color(0xFF0B0F0C),
            surfaceContainer = Color(0xFF121713), surfaceContainerHigh = Color(0xFF181D19), surfaceContainerHighest = Color(0xFF202521), surfaceVariant = Color(0xFF202521), surfaceBright = Color(0xFF2D312E))
        else -> d
    }
}
